    sep_cols = [c for c in range(w) if g[0][c] != 0 and all(g[r][c] == g[0][c] for r in range(h))]
    rbounds = [-1] + sep_rows + [h]
    cbounds = [-1] + sep_cols + [w]
    panels = [(cbounds[i] + 1, cbounds[i + 1]) for i in range(len(cbounds) - 1)]
    for ri in range(len(rbounds) - 1):
        r0, r1 = rbounds[ri] + 1, rbounds[ri + 1]
        if r0 >= r1:
            continue
        active = [i for i, (a, b) in enumerate(panels) if any(g[r][c] != 0 for r in range(r0, r1) for c in range(a, b))]
        if not active:
            continue
        # Adjacent occupied panels are a mirrored pair. A lone motif is reflected
        # into the next panel to its right (or left at the right edge).
        pairs = [(i, i + 1) for i in active if i + 1 in active]
        if not pairs and len(active) == 1:
            i = active[0]
            j = i + 1 if i + 1 < len(panels) else i - 1
            if j >= 0:
